# ! [allow (incomplete_features ,)] # ! [feature (generic_const_exprs)] use futures :: executor :: block_on ; fn main () { use std :: env ; env :: set_var ("RUST_BACKTRACE" , "1") ; env :: set_var ("RUST_LOG" , "info") ; block_on (test ()) ; } fn concat < const A : usize , const B : usize > (a : [f32 ; A] , b : [f32 ; B]) -> [f32 ; A + B] { let mut array = [0f32 ; A + B] ; for (loc , value) in array . iter_mut () . zip (a . iter () . chain (b . iter ())) { * loc = * value ; } array } async fn reverse < const A : usize > (x : [f32 ; A]) -> [f32 ; A] { let mut array = [0f32 ; A] ; for (loc , value) in array . iter_mut () . rev () . zip (x . iter ()) { * loc = * value ; } array } async fn test () { let a = [0.0] ; println ! ("{:?}" , a) ; let b = [1.0 , 2.0] ; println ! ("{:?}" , b) ; let ab = concat (a , b) ; println ! ("{:?}" , ab) ; let ba = reverse (ab) . await ; println ! ("{:?}" , ba) ; }